INO_st.name='INO';
INO_st.lat=44.35;
INO_st.lon=26.03;
INO_st.alt=93;
INO_st.env='con';
INO_st.footp='U';
%%

INO_rd= read_all_data_INO_Ttable('AE33','lev2','C:/github_trend/raw_data/INO_AE33_IPCC/');%read all nasa ames read_betsy_2026('INO_tsi_psap_clap_eco',INO_st.name); %[output:9164eee1]
names_rd=fieldnames(INO_rd_d);
%%

% change name
INO_rd.end_time=[]; %[output:2507e795]
INO_rd.numflag=[]
INO_rd.Properties.VariableNames{1}='Ba1_A';
INO_rd.Properties.VariableNames{2}='Ba2_A';
INO_rd.Properties.VariableNames{3}='Ba3_A';
INO_rd.Properties.VariableNames{4}='Ba4_A';
INO_rd.Properties.VariableNames{5}='Ba5_A';
INO_rd.Properties.VariableNames{6}='Ba6_A';
INO_rd.Properties.VariableNames{7}='Ba7_A';
INO_rd_d=retime(INO_rd,'daily',@nanmedian);
names_rd=fieldnames(INO_rd_d);
%%
datevec(INO_rd.Time(1)) %data since 2016 %[output:87b350db]
datevec(INO_rd.Time(end)) % 2025 %[output:47a229f5]
% % prctile(INO_rd.U0_S11,[5 50 95]) % < 38% ok no need to compute dry trend
% % prctile(INO_rd.U1_S11,[5 50 95])
figure; %[output:47ed9f9a]
plot(INO_rd_d.Time, INO_rd_d{:,1:7},'.'); %[output:47ed9f9a]
ylabel('Abs. Coef.'); %[output:47ed9f9a]
title('INO'); %[output:47ed9f9a]
grid on; %[output:47ed9f9a]
%%
% BP detection for abs

names_abs=names_rd(startsWith(names_rd,'Ba'));
break_INO_abs_BP=change_point_analysis_Def(INO_rd_d,names_abs,0.05,'INO','abs'); %[output:9dd000cd] %[output:5d35e574] %[output:734d9935] %[output:9834973c] %[output:420f02f9] %[output:7025b503]
T_INO_abs_BP=make_table_breakpoints_def(break_INO_abs_BP);
%%
lambdaAE7=[370 470 520 590 660 880 950];
INO_cal=compute_exp_D(INO_rd_d,names_abs,lambdaAE7 ); %[output:509ea5c9] %[output:6fc28c82] %[output:103962bd] %[output:843b51bc] %[output:8d77ed97] %[output:8b923fee] %[output:892d6782] %[output:4a6daef2] %[output:8f838f80] %[output:29a14e14] %[output:5f9652b8] %[output:80b5e8ad] %[output:674dd939] %[output:711b266c] %[output:2ddd64be]
plotFigControl_cal(INO_cal,INO_st.name); %[output:570fe13f] %[output:29a1899e] %[output:2b928d36]
%%
% BP detection for abs exp


break_INO_expA_BP=change_point_analysis_Def(INO_cal,{'expA_fit'},0.05,'INO','abs exp'); %[output:5b5c3e7d] %[output:1000a58d]
T_INO_expA_BP=make_table_breakpoints_def(break_INO_expA_BP);
%%
INO_tr=outerjoin(INO_rd_d,INO_cal);
INO_tr.y=year(INO_tr.Time);
% begin at the beginning of a year: 2007 for abs, 2009 for scat
%end: 2025
P=timerange('2016-01-01','2026-01-01');
INO_tr=INO_tr(P,:);

% % % begin at the beginning of a year:  2009 for scat
% % Ps=timerange('2007-01-01','2009-01-01');
% % names=fieldnames(INO_tr);
% % c=startsWith(names,["Bs";"Bbs";"U"]);
% % N=names(c)
% % for i=1:length(N)
% %     INO_tr.(N{i})(Ps)=NaN;
% % end

%change in RH: compute RH trend

% % % abs change for green wavelenght to compute SSA
% % INO_tr.BaR_A11=INO_tr.BaR0_A.*(637/550);
% % INO_tr.BaR0_A=[];
% % INO_cal2=compute_exp_SSA(INO_tr,lambdaSC, lambdaAE);
% % INO_cal2.SSA0=INO_tr.BsG0_S./(INO_tr.BsG0_S+INO_tr.BaR_A11);
% % INO_tr=outerjoin(INO_tr, INO_cal2);

%do not compute trend on B, R and exp with red
INO_tr.Ba1_A=[];
INO_tr.Ba2_A=[];
INO_tr.Ba4_A=[];
INO_tr.Ba5_A=[];
INO_tr.Ba6_A=[];
INO_tr.Ba7_A=[];

INO_tr.expA_bgAE=[];
INO_tr.expA_brAE=[];
INO_tr.expA_grAE=[];
%%
%data in Mm-1
INO_tr.Ba3_A=INO_tr.Ba3_A.*1e6;
%%
[INO_result_MK,INO_result_LMSlog,INO_result_LMSlin]=all_trend_STN(INO_tr,INO_st); %[output:4f80d62a] %[output:20bb94d5] %[output:0da3b369] %[output:6c9c63d5] %[output:9fcb8e86] %[output:521515e6] %[output:5a47d95b] %[output:111e3216]

writetable(INO_result_MK,'INO_res_MK.txt'); %, 'delimiter',',' )
writetable(INO_result_LMSlog,'INO_res_LMSlog.txt'); 
writetable(INO_result_LMSlin,'INO_res_LMSlin.txt'); 
plot_10y_in_two(INO_result_MK, INO_st,'y'); %[output:1445e66a] %[output:93c31ac4]

